import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def render_report(template_path, output_path, params):
    """Render a report using wkhtmltopdf with user-supplied parameters."""
    # Build command with user-controlled header/footer
    cmd = ['wkhtmltopdf', '--enable-local-file-access']

    if params.get('header'):
        cmd.extend(['--header-html', params['header']])
    if params.get('footer'):
        cmd.extend(['--footer-html', params['footer']])
    if params.get('margin_top'):
        cmd.extend(['--margin-top', str(params['margin_top'])])
    if params.get('orientation'):
        cmd.extend(['--orientation', params['orientation']])

    cmd.extend([template_path, output_path])

    result = subprocess.run(cmd, capture_output=True, timeout=30)
    return result.returncode == 0

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from HTML template with user parameters."""
    if 'template' not in request.files:
        return jsonify({'error': 'No template file'}), 400

    template_file = request.files['template']
    filename = secure_filename(template_file.filename)

    if not filename.endswith('.html'):
        return jsonify({'error': 'Only HTML templates allowed'}), 400

    # Parse rendering parameters
    params = {}
    if request.form.get('params'):
        try:
            params = yaml.safe_load(request.form['params'])
        except yaml.YAMLError:
            return jsonify({'error': 'Invalid params YAML'}), 400

    # Save template
    template_path = os.path.join(UPLOAD_DIR, filename)
    template_file.save(template_path)

    # Generate output path
    output_filename = filename.rsplit('.', 1)[0] + '.pdf'
    output_path = os.path.join(UPLOAD_DIR, output_filename)

    # Render the report
    success = render_report(template_path, output_path, params)

    if success:
        return jsonify({'status': 'ok', 'path': f'/reports/{output_filename}'})
    else:
        return jsonify({'error': 'Rendering failed'}), 500

@app.route('/api/reports/batch', methods=['POST'])
def batch_generate():
    """Batch generate reports from a manifest file."""
    manifest = request.get_json()
    if not manifest or 'jobs' not in manifest:
        return jsonify({'error': 'Invalid manifest'}), 400

    results = []
    for job in manifest['jobs']:
        template_url = job.get('template_path', '')
        # Validate path doesn't escape upload dir
        full_path = os.path.realpath(os.path.join(UPLOAD_DIR, template_url))
        if not full_path.startswith(os.path.realpath(UPLOAD_DIR)):
            results.append({'error': 'path traversal blocked', 'job': job.get('id')})
            continue

        output_path = full_path.rsplit('.', 1)[0] + '.pdf'
        params = job.get('params', {})
        success = render_report(full_path, output_path, params)
        results.append({'job': job.get('id'), 'success': success})

    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
